package dev.industrialtechnology.capacitor;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class BankLedgerTest {
    private List<BankLedger.Cell> cells(int n,long energy){List<BankLedger.Cell> c=new ArrayList<BankLedger.Cell>();for(int i=0;i<n;i++)c.add(new BankLedger.Cell(25000000,energy,null));return c;}
    private BankLedger bank(List<BankLedger.Cell> c){return new BankLedger(c,25000,25000);}
    private long sum(List<BankLedger.Cell> c){long n=0;for(BankLedger.Cell x:c){assertTrue(x.energy()>=0&&x.energy()<=x.capacity);n+=x.energy();}return n;}
    @Test public void singleBankDefault(){BankLedger l=bank(cells(1,0));assertEquals(25000000,l.capacity());assertEquals(25000,l.maxInput());assertEquals(25000,l.maxOutput());assertEquals(0,l.stored());}
    @Test public void inputSimulationDoesNotSpend(){BankLedger l=bank(cells(2,0));for(int i=0;i<12;i++)assertEquals(50000,l.receive(70000,1,-1,true));assertEquals(0,l.stored());assertEquals(50000,l.receive(70000,1,-1,false));assertEquals(0,l.receive(1,1,-1,false));}
    @Test public void outputSimulationDoesNotSpend(){BankLedger l=bank(cells(1,100000));for(int i=0;i<12;i++)assertEquals(25000,l.extract(70000,1,-1,true));assertEquals(100000,l.stored());assertEquals(25000,l.extract(70000,1,-1,false));assertEquals(0,l.extract(1,1,-1,false));}
    @Test public void oneSharedBudgetAcrossCalls(){BankLedger l=bank(cells(5,100000));for(int i=0;i<5;i++)assertEquals(25000,l.extract(25000,2,-1,false));assertEquals(0,l.extract(25000,2,-1,false));assertEquals(125000,l.extract(200000,3,-1,false));assertEquals(125000,l.lastOutput(3));}
    @Test public void configuredLimitsClamp(){BankLedger l=bank(cells(1,100000));assertEquals(17000,l.receive(100000,1,17000,false));assertEquals(25000,l.extract(100000,1,Long.MAX_VALUE,false));assertEquals(0,l.receive(1,2,0,false));assertEquals(0,l.extract(1,2,0,false));}
    @Test public void mergeRetainsOwnershipAndAlreadySpentBudget(){List<BankLedger.Cell> a=cells(2,100000),b=cells(3,200000);BankLedger left=bank(a),right=bank(b);left.extract(20000,9,-1,false);right.extract(40000,9,-1,false);List<BankLedger.Cell> all=new ArrayList<BankLedger.Cell>(a);all.addAll(b);BankLedger merged=bank(all);assertEquals(740000,merged.stored());assertEquals(60000,merged.outputUsed(9));assertEquals(65000,merged.extract(100000,9,-1,false));assertEquals(sum(all),merged.stored());}
    @Test public void splitCannotResetQuotaOrCopyEnergy(){List<BankLedger.Cell> c=cells(10,1000000);BankLedger whole=bank(c);whole.receive(240000,10,-1,false);whole.extract(220000,10,-1,false);BankLedger a=bank(c.subList(0,5)),b=bank(c.subList(5,10));assertEquals(whole.stored(),a.stored()+b.stored());assertEquals(10000,a.receive(1000000,10,-1,false)+b.receive(1000000,10,-1,false));assertEquals(30000,a.extract(1000000,10,-1,false)+b.extract(1000000,10,-1,false));}
    @Test public void billionsDoNotOverflow(){BankLedger l=bank(cells(200,25000000));assertEquals(5000000000L,l.stored());assertEquals(5000000000L,l.capacity());assertEquals(5000000,l.extract(Integer.MAX_VALUE,1,-1,false));assertEquals(4995000000L,l.stored());}
    @Test public void partialReceiverRefundsOriginalCellsAndQuota(){List<BankLedger.Cell> c=cells(5,100000);BankLedger l=bank(c);BankLedger.Reservation r=l.reserveOutput(125000,1,-1);assertEquals(375000,l.stored());assertEquals(17000,r.settle(17000));assertEquals(483000,sum(c));assertEquals(17000,l.outputUsed(1));assertEquals(108000,l.extract(200000,1,-1,false));}
    @Test public void rejectedOutputReservesRefundSpace(){BankLedger.Cell c=new BankLedger.Cell(100,100,null);BankLedger l=new BankLedger(Arrays.asList(c),100,100);BankLedger.Reservation r=l.reserveOutput(80,1,-1);assertEquals(0,l.receive(80,1,-1,false));r.settle(0);assertEquals(100,c.energy());assertEquals(100,l.stored());assertEquals(100,l.extract(100,1,-1,false));}
    @Test(expected=IllegalStateException.class) public void cannotSettleTwice(){BankLedger.Reservation r=bank(cells(1,100)).reserveOutput(50,1,-1);r.settle(50);r.settle(50);}
    @Test public void idleAndSkippedEpochsReportZero(){BankLedger l=bank(cells(1,0));l.receive(20000,2,-1,false);assertEquals(20000,l.lastInput(3));assertEquals(0,l.lastInput(4));assertEquals(0,l.lastInput(1000));assertEquals(25000,l.receive(40000,1000,-1,false));}
    @Test public void capacityBoundAndNegativeRequests(){BankLedger l=bank(cells(1,24999000));assertEquals(1000,l.receive(Integer.MAX_VALUE,1,-1,false));assertEquals(0,l.receive(-1,2,-1,false));assertEquals(0,l.extract(Integer.MIN_VALUE,2,-1,false));assertEquals(25000000,l.stored());}
    @Test public void randomizedConservationWithTopologyChanges(){Random r=new Random(77219);List<BankLedger.Cell> c=cells(27,0);long total=0;BankLedger l=bank(c);for(int tick=0;tick<10000;tick++){if(tick%7==0){Collections.shuffle(c,r);l=bank(c);}boolean input=r.nextBoolean(),sim=r.nextInt(4)==0;int request=r.nextInt(2000000);int moved=input?l.receive(request,tick/4,-1,sim):l.extract(request,tick/4,-1,sim);if(!sim)total+=input?moved:-moved;assertEquals(total,l.stored());assertEquals(total,sum(c));assertTrue(l.inputUsed(tick/4)<=l.maxInput());assertTrue(l.outputUsed(tick/4)<=l.maxOutput());}}
    @Test public void aggregateRatesAboveIntAcceptSafeIntCalls(){List<BankLedger.Cell> c=new ArrayList<BankLedger.Cell>();for(int i=0;i<4;i++)c.add(new BankLedger.Cell(1000000000000L,0,null));BankLedger l=new BankLedger(c,1000000000,1000000000);assertEquals(4000000000L,l.maxInput());assertEquals(Integer.MAX_VALUE,l.receive(Integer.MAX_VALUE,1,-1,false));assertEquals(1852516353,l.receive(Integer.MAX_VALUE,1,-1,false));assertEquals(4000000000L,l.stored());assertEquals(Integer.MAX_VALUE,l.extract(Integer.MAX_VALUE,1,-1,false));assertEquals(1852516353,l.extract(Integer.MAX_VALUE,1,-1,false));assertEquals(0,l.stored());}
    @Test public void mergeRetainsPreviousTickStatsAfterThisTickHasStarted(){List<BankLedger.Cell> a=cells(1,100000),b=cells(1,100000);BankLedger left=bank(a),right=bank(b);left.receive(10000,2,-1,false);right.receive(15000,2,-1,false);left.extract(7000,2,-1,false);right.extract(9000,2,-1,false);left.receive(3000,3,-1,false);List<BankLedger.Cell> all=new ArrayList<BankLedger.Cell>(a);all.addAll(b);BankLedger merged=bank(all);assertEquals(25000,merged.lastInput(3));assertEquals(16000,merged.lastOutput(3));assertEquals(3000,merged.inputUsed(3));}
}
